head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.id = 1;
scwin.dpId = "";

// ID 순번
            // 선택된 DP ID

///////// 2. 초기화 영역 /////////
            scwin.onpageload = function() {

                scwin.vScrenID = "ULDTMS02010.xml";
                let historyCont = "";

                edi_editor.bind("beforeinput", function (e) {

                    if (!$c.util.isEmpty(e.data)) {                        
                        e.preventDefault();
                    } else if (e.inputType === "insertCompositionText") {
                        historyCont = edi_editor.getHTML();
                    }
                });

                edi_editor.bind("input", function (e) {

                    console.log("삭제 처리 ");
                    edi_editor.setHTML("");
                });

                edi_editor.bind("onkeydown", function (e) {

                    //if (e.key !== "Enter" & e.key != "Tab" & e.key != " " && e.key != "Backspace" 
					//					  && e.key != "Delete"  && (e.key).indexOf("Arrow") < 0) {

                    // Backspace와 Delete, Arrow만 처리	
					if (e.key === "Backspace" || e.key === "Delete" || (e.key).indexOf("Arrow") > -1) {
						const selection = window.getSelection();
						if (!selection.rangeCount) {
							return;
						}

						// 선택영역 삭제처리 해제
						const range = selection.getRangeAt(0);
						if (!range.collapsed) {
							e.preventDefault();
							return false;
						}
						const container = range.startContainer;
						const offset = range.startOffset;
						if (container.nodeType === Node.TEXT_NODE) {
							// 앞 첫글자나 현재 위치의 글자
							let nChar = "";
							if (e.key === "ArrowLeft") {
								nChar = container.textContent.charAt(offset - 1);
							} else if (e.key === "ArrowRight") {
								nChar = container.textContent.charAt(offset);
							} else {
								nChar = (e.key === "Delete")? container.textContent.charAt(offset):container.textContent.charAt(offset - 1);
							}

							if (nChar === " " || nChar === "") {
								return;
							} else {
								e.preventDefault();																
								return false;
							}							
						}
					} else {
                        e.preventDefault();
                    }                   
                });

                // 초기화
                //grp_3_1.setStyle("display", "none");
                //grp_3_2.setStyle("display", "none");
                //grp_4_1.setStyle("display", "none");
                //grp_4_2.setStyle("display", "none");
                //grp_5.setStyle("display", "none");

                //grp_nonLabel.hide();
                //grp_label.hide();
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.btn_search_onclick = async function (e) {

                const url_ = "/ui/TMS/ULDTMS03011.xml";
                const options = {
                    id: "ULDTMS03011_POP",
                    popupName: "서식조회",
                    width: "1000",
                    height: "650",
                    frameModal: "top"
                };

                const result = await $c.win.openPopup(url_, options, {});
                if (!$c.util.isEmpty(result)) {
                    dma_form.set("formCd", result.formCd);
                    dma_form.set("formVer", result.formVer);
                    dma_form.set("formKorNm", result.formKorNm);
                    dma_form.set("wrtrptMaindocTpCd", result.wrtrptMaindocTpCd);
                    dma_form.set("wrtrptMaindocTpNm", result.wrtrptMaindocTpNm);
                    dma_form.set("roleId", result.roleId);
                    dma_form.set("txnId", result.txnId);                    

                    ibx_title.setValue(result.formKorNm);
                    // 서식 Clob 조회
                    $c.sbm.execute(sbm_file, dma_form.getJSON());
                }              
            };

            scwin.btn_title_onclick = function (e) {

                const div = document.createElement("div");
			    div.setAttribute("style", "left:73px; top:102px; width:592px; min-height:28px; font-family:돋움체; font-size:10px;cursor:pointer");
                div.setAttribute("data-ix-id", "title-1");
                div.setAttribute("krx-tp:data-type", "title");

                // 내용 등록하기 
                const p = document.createElement("p");
                p.setAttribute("data-ix-id", "title-1");
                p.setAttribute("style", "cursor:pointer");
                p.setAttribute("krx-tp:data-kodefault", "11");
                p.setAttribute("krx-tp:data-endefault", "22");
                p.textContent = "[타이틀]";

                div.appendChild(p);

				scwin.fnWrite(div);
            };

            scwin.btn_label_onclick = function (e) {

			    const span = document.createElement("span");
			    span.setAttribute("style", "cursor:pointer");
                span.setAttribute("data-ix-id", "caret-1");                
                span.setAttribute("data-type", "label");
                span.setAttribute("data-kodefault", "33");
                span.setAttribute("data-endefault", "444");
                span.setAttribute("data-prefix", "444");  // data-prefix="ko:1. ; en:1."; 
                span.contentEditable = false;

                span.textContent = "[LABEL#]";                           

				scwin.fnWrite(span);

                scwin.dpId = "DRT001";
                // DP목록에 추가
                dlt_list.insertRow(dlt_list.getRowCount());
                dlt_list.setCellData(dlt_list.getRowCount()-1, "dpId", "DRT001");
                dlt_list.setCellData(dlt_list.getRowCount()-1, "comTpCd", "TEXT");
                dlt_list.setCellData(dlt_list.getRowCount()-1, "dpKorLabl", "테스트테스트");
                dlt_list.setCellData(dlt_list.getRowCount()-1, "dpEngLabl", "NICE");
                dlt_list.setCellData(dlt_list.getRowCount()-1, "libdocDpYn", "N");
            };

            scwin.btn_text_onclick = function (e) {

                scwin.id = scwin.id + 1;

                const span = document.createElement("span");
                span.setAttribute("style", "cursor:pointer");
                span.setAttribute("data-ix-id", "caret-1");                
                span.setAttribute("data-tag", "ix:nonnumeric");

                const ns = "http://www.xbrl.org/2013/inlineXBRL";                
                const tag = document.createElementNS(ns, "ix:nonnumeric");

                tag.setAttribute("style", "cursor:pointer");
                tag.setAttribute("data-ix-id", "caret-" + scwin.id);
                tag.textContent = "[TEXT #" + scwin.id + "]";

                span.appendChild(tag);

				scwin.fnWrite(span);
            };

            scwin.edi_editor_oncontentclick = function (e) {

				console.log(e);
				console.log(e.target.textContent);
                // 객체인지 여부 체크
                if (e.target.getAttribute("data-type") === "label") {
                    grp_nonLabel.hide();
                    grp_label.show();                    
                }                                                

				// 객체를 선택했는지 체크
				if (e.target.tagName === "SPAN") {
					const range = document.createRange();
					const selection = window.getSelection();

					//range.selectNodeContents(e.target.closest("span"));
                    range.setStartAfter(e.target.closest("span"));
					range.collapse(false);

					selection.removeAllRanges();
					selection.addRange(range);                                        
				}                   
            }

            scwin.btn_element_onclick = async function (e) {

                if (!$c.util.isEmpty(dma_form.get("txnId"))) {
                    const url_ = "/ui/TMS/ULDTMS02020.xml";
                    const options = {
                        id: "ULDTMS02020_POP",
                        popupName: " ",
                        width: "1100",
                        height: "650",
                        frameModal: "top"
                    };

                    let params = {};                    
                    params.txnId = dma_form.get("txnId");

                    const result = await $c.win.openPopup(url_, options, params);
                    if (!$c.util.isEmpty(result)) {                                                
                        ibx_element.setValue(result.elmtId);
                        // 임시로 값을 셋팅
                        document.getElementById(ibx_element.getID()).setAttribute("elmtKorLabl", result.elmtKorLabl);
                        document.getElementById(ibx_element.getID()).setAttribute("elmtEngLabl", result.elmtEngLabl);

                        // Enum형 여부 
                        if (!$c.util.isEmpty(result.enumList) && result.enumList.length > 0) {
                            document.getElementById(ibx_element.getID()).setAttribute("enumList", JSON.stringify(result.enumList));
                        } else {
                            document.getElementById(ibx_element.getID()).setAttribute("enumList", "");
                        }
                    }
                } else {
                    $c.win.alert("텍사노미 ID가 없는 서식은 ELEMENT를 추가 할 수 없습니다.");
                }
            };

            scwin.btn_axies_onclick = async function (e) {

                if (!$c.util.isEmpty(dma_form.get("txnId"))) {
                    const url_ = "/ui/TMS/ULDTMS02030.xml";
                    const options = {
                        id: "ULDTMS02030_POP",
                        popupName: "축/멤버 추가",
                        width: "1100",
                        height: "720",
                        frameModal: "top"
                    };

                    let params = {};                
                    params.txnId = dma_form.get("txnId");

                    // dataPoint 정보 (향후 추가)
                    let list = [];
                    let data1 = {};
                    data1.dataId = "A102010601";
                    data1.dataNm = "A102010601:주권관련 사채권 유형";                
                    data1.enumList = "01:전환사채()|02:신주인수권부사채(:)";
                    list.push(data1);

                    let data2 = {};
                    data2.dataId = "A102010602";
                    data2.dataNm = "A102010602:유치권 유형";

                    data2.enumList = "01:김밥(Bob)|02:라면(Ramen)|03:우동(WooDong)";
                    list.push(data2);
                    params.dataPoint = list;

                    const result = await $c.win.openPopup(url_, options, params);                
                    if (!$c.util.isEmpty(result)) {
                        // 기존 Node를 수집
                        // "추가" 버튼만 다시 갖고 있다가 재생성 처리해야 웹스퀘어가 "추가" 버튼을 맨밑으로 이동 처리 해줌.
                        const insBtn = grp_axis.getChildren()[grp_axis.getChildren().length - 1];

                        // FLEX DIV
                        const flexDiv = document.createElement("div");
                        flexDiv.className = "w2group flex";

                        const input1 = document.createElement("input");
                        input1.setAttribute("type", "text");
                        input1.setAttribute("name", "ibx_axis");
                        input1.setAttribute("readonly", "true");
                        input1.setAttribute("style", "width:100%;");
                        // 추가 속성에 데이타 저장
                        input1.setAttribute("axisId", result.axisId);
                        input1.setAttribute("axisLabl", result.axisLabl);
                        input1.setAttribute("axisTypCd", result.axisTypCd);
                        input1.setAttribute("membId", result.membId);
                        input1.setAttribute("membLabl", result.membLabl);
                        input1.setAttribute("refDpId", result.refDpId);
                        input1.setAttribute("condBasDpId", result.condBasDpId);

                        // Enum형 여부 
                        if (!$c.util.isEmpty(result.enumList) && result.enumList.length > 0) {
                            input1.setAttribute("enumList", JSON.stringify(result.enumList));
                        } else {
                            input1.setAttribute("enumList", "");
                        }
                        input1.className = "w2input";
                        input1.setValue(result.axisLabl);

                        const input2 = document.createElement("input");
                        input2.setAttribute("id", "btn_axis");
                        input2.setAttribute("type", "button");
                        input2.className = "w2trigger btn_cm delete icon";

                        input2.textContent = "Delete";
                        input2.addEventListener("click", function (e) {                        
                             e.target.parentNode.remove();
                        });

                        flexDiv.appendChild(input1);
                        flexDiv.appendChild(input2);

                        // 차례로 처리 마지막 Node에서 신규 등록
                        grp_axis.appendChild(flexDiv);
                        // 추가버튼 이동
                        grp_axis.appendChild(insBtn);                   
                    }
                } else {
                    $c.win.alert("텍사노미 ID가 없는 서식은 축/멤버를 추가 할 수 없습니다.");
                }
            };

            scwin.btn_unitForm_onclick = async function (e) {

                const url_ = "/ui/TMS/ULDTMS02050.xml";
                const options = {
                    id: "ULDTMS02050_POP",
                    popupName: "단위서식 선택",
                    width: "640",
                    height: "310",
                    frameModal: "top"
                };

                let params = {};
                params.formCd = dma_form.get("formCd");

                const result = await $c.win.openPopup(url_, options, params);
                console.log(result);
                if (!$c.util.isEmpty(result)) {

                }                
            };

            scwin.ibx_identifier_onclick = function (e) {

                scwin.fnCommonPop("Identifier", "Identifier 설정");
            };

            scwin.ibx_period_onclick = function (e) {

                scwin.fnCommonPop("Period", "Period 설정");
            };

            scwin.ibx_unit_onclick = function (e) {

                scwin.fnCommonPop("Unit", "Unit 설정");
            };

            scwin.ibx_decimals_onclick = function (e) {

                scwin.fnCommonPop("Decimals", "Decimals 설정");
            };

            scwin.btn_file_onclick = function (e) {

                upd_file.openFileDialog();
            };

            scwin.upd_file_oninputvaluechange = function (fileName) {

                $c.tms.sendFileUpload(upd_file, "/api/form/formInfo/upload", "upload", function (e) {
                    // HTML을 Editor 등록 
                    edi_editor.setHTML(e.body.formInlnfile);
                });                           
            };

            scwin.btn_update_onclick = function (e) {

                for (let i=0; i < dlt_list.getRowCount(); i++) {                    
                    // 선택된 DP ID 검색 
                    if (scwin.dpId === dlt_list.getCellData(i, "dpId")) {   
                        dlt_list.setCellData(i, "formCd", dma_form.get("formCd"));
                        dlt_list.setCellData(i, "formVer", dma_form.get("formVer"));

                        // IDENTIFIER
                        dlt_list.setCellData(i, "idntfTpCd", ibx_identifier.getValue());
                        dlt_list.setCellData(i, "idntfCmCd", "");
                        dlt_list.setCellData(i, "idntfRefDpId", "");

                        // PERIOD
                        dlt_list.setCellData(i, "pdTpCd", ibx_period.getValue());
                        dlt_list.setCellData(i, "pdCmCd", "");
                        dlt_list.setCellData(i, "idntfRpdRefDpIdefDpId", "");

                        // Element
                        dlt_list.setCellData(i, "elmtId", ibx_element.getValue());
                        dlt_list.setCellData(i, "elmtKorLabl", document.getElementById(ibx_element.getID()).getAttribute("elmtKorLabl"));
                        dlt_list.setCellData(i, "elmtEngLabl", document.getElementById(ibx_element.getID()).getAttribute("elmtEngLabl"));

                        // Enum형 삭제 처리
                        for (let j=dlt_enumList.getRowCount()-1; j > -1; j--) {
                            if (scwin.dpId === dlt_enumList.getCellData(j, "dpId")) {
                                dlt_enumList.deleteRow(j);
                            }
                        }
                        // Axis 삭제 처리
                        for (let j=dlt_axisList.getRowCount()-1; j > -1; j--) {
                            if (scwin.dpId === dlt_axisList.getCellData(j, "dpId")) {
                                dlt_axisList.deleteRow(j);
                            }
                        }

                        // Enum형 여부 
                        if (!$c.util.isEmpty(document.getElementById(ibx_element.getID()).getAttribute("enumList"))) {
                            const enumList = JSON.parse(document.getElementById(ibx_element.getID()).getAttribute("enumList"));
                            let num_ = 1;
                            enumList.forEach(function(cont) {
                                dlt_enumList.insertRow(dlt_enumList.getRowCount());
                                dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "formCd", dma_form.get("formCd"));
                                dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "formVer", dma_form.get("formVer"));
                                dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "dpId", scwin.dpId);
                                dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumSeq", num_++);
                                dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumVal", cont.substring(0, cont.indexOf(":")));
                                dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumKorLabl", cont.substring(cont.indexOf(":") + 1, cont.indexOf("(")));
                                dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumEnLabl", cont.substring(cont.indexOf("(") + 1, cont.indexOf(")")));
                            });                            
                        }

                        // Aixs
                        const axisList = [];
                        const elems = document.getElementsByName("ibx_axis");                        
                        if (!$c.util.isEmpty(elems) && elems.length > 0) {                            
                            for (j=0; j < elems.length; j++) {

                                // 조건부 축 리스트 삭제 처리
                                for (let k=dlt_condList.getRowCount()-1; k > -1; k--) {
                                    if (dlt_axisList.getCellData(j, "axisId") === dlt_condList.getCellData(k, "axisId") &&
                                        dlt_axisList.getCellData(j, "membId") === dlt_condList.getCellData(k, "membId")) {
                                        dlt_condList.deleteRow(j);
                                    }                                    
                                } 
                                dlt_axisList.insertRow(dlt_axisList.getRowCount());
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "formCd", dma_form.get("formCd"));
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "formVer", dma_form.get("formVer"));
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "dpId", scwin.dpId);
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "axisSeq", j+1);
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "axisId", elems[j].getAttribute("axisId"));
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "axisLabl", elems[j].getAttribute("axisLabl"));
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "axisTpCd", elems[j].getAttribute("axisTypCd"));
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "membId", elems[j].getAttribute("membId"));
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "membLabl", elems[j].getAttribute("membLabl"));
                                dlt_axisList.setCellData(dlt_axisList.getRowCount()-1, "refDpId", elems[j].getAttribute("refDpId"));

                                // Enum형 여부 
                                if (!$c.util.isEmpty(elems[j].getAttribute("enumList"))) {
                                    const enumList = JSON.parse(elems[j].getAttribute("enumList"));
                                    let num_ = 1;
                                    enumList.forEach(function(enumL) {
                                        dlt_enumList.insertRow(dlt_enumList.getRowCount());
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "formCd", dma_form.get("formCd"));
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "formVer", dma_form.get("formVer"));
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "dpId", scwin.dpId);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumSeq", num_++);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumVal", enumL.enumVal);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumKorLabl", enumL.enumKorLabl);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "enumEnLabl", enumL.enumEnLabl);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "axisId", enumL.mappAxisId);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "membId", enumL.membId);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "membLabl", enumL.membLabl);
                                        dlt_enumList.setCellData(dlt_enumList.getRowCount()-1, "membOrd", enumL.membOrd);           
                                    });
                                }

                                // 조건부 추가
                                if (!$c.util.isEmpty(elems[j].getAttribute("condBasDpId"))) {

                                    console.log(elems[j].getAttribute("axisId"));
                                    console.log(elems[j].getAttribute("membId"));
                                    console.log(elems[j].getAttribute("condBasDpId"));

                                    dlt_condList.insertRow(dlt_condList.getRowCount());
                                    dlt_condList.setCellData(dlt_condList.getRowCount()-1, "formCd", dma_form.get("formCd"));
                                    dlt_condList.setCellData(dlt_condList.getRowCount()-1, "formVer", dma_form.get("formVer"));
                                    dlt_condList.setCellData(dlt_condList.getRowCount()-1, "axisId", elems[j].getAttribute("axisId"));
                                    dlt_condList.setCellData(dlt_condList.getRowCount()-1, "membId", elems[j].getAttribute("membId"));
                                    dlt_condList.setCellData(dlt_condList.getRowCount()-1, "condBasDpId", elems[j].getAttribute("condBasDpId"));
                                }
                            }
                        }                        

                        // UNIT
                        dlt_list.setCellData(i, "unitTypCd", "");
                        dlt_list.setCellData(i, "unitCmCd", "");
                        dlt_list.setCellData(i, "unitRefDpId", "");

                        // DECIMALS
                        dlt_list.setCellData(i, "dcmlTpCd", "");
                        dlt_list.setCellData(i, "dcmlCmCd", "");
                        dlt_list.setCellData(i, "dcmlRefDpId", "");

                        // 입력옵션
                        console.log(chk_input);                        
                        dlt_list.setCellData(i, "mandtryYn", "");                        

                        break;
                    }                                            
                }
            };

            scwin.btn_save_onclick = function (e) {

                const params = {};                 
                // 서식 코드
                params.formCd = dma_form.get("formCd");
                // 서식 버전
                params.formVer = dma_form.get("formVer");

                // 데이터 포인트 매핑 리스트
                params.dpList = dlt_list.getAllJSON(); 
                // 차원/축 리스트
                params.axisList = dlt_axisList.getAllJSON();                 
                // enumulation 리스트
                params.enumList = dlt_enumList.getAllJSON();                
                // 축/멤버 조건부 축 리스트
                params.axisCondList = dlt_condList.getAllJSON();                

                console.log(params);              
                $c.sbm.execute(sbm_save, params);
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_file_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;                    
                if (result.success) {

                    const obj = result.body;
                    edi_editor.setHTML(obj.formFileContent);

                    //grp_3_1.setStyle("display", "");
                    //grp_3_2.setStyle("display", "flex");
                    //grp_4_1.setStyle("display", "");
                    //grp_4_2.setStyle("display", "");
