            scwin.fnWrite = function (obj) {

				edi_editor.editHTML(function (root, selection) {

                	if (!selection) {                    
                    	return;
                	}
                	selection.range.deleteContents();               
                	selection.range.insertNode(obj);

					// 커서 위치 이동
					selection.range.setStartAfter(obj);
					selection.range.setEndAfter(obj);					
            	});
                historyCont = edi_editor.getHTML();
